import { getComponentByName } from '../utils/dataLoader.js';

/**
 * Get component preview information and basic usage
 */
export async function previewComponent(args) {
  const { componentName } = args;

  try {
    // Find component
    const component = getComponentByName(componentName);
    if (!component) {
      return {
        content: [
          {
            type: 'text',
            text: `Component "${componentName}" not found. Use search-react-bits-components to find available components.`
          }
        ]
      };
    }

    // Generate preview information
    const preview = generateComponentPreview(componentName, component);

    return {
      content: [
        {
          type: 'text',
          text: preview
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error generating preview: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Generate comprehensive component preview
 */
function generateComponentPreview(componentName, component) {
  let output = `# ${capitalizeFirst(componentName)} - Component Preview\n\n`;
  
  // Basic info
  output += `**Name:** ${componentName}\n`;
  output += `**Category:** ${component.category}\n`;
  output += `**Description:** ${component.description}\n\n`;

  // Visual description
  output += `## Visual Description\n\n`;
  output += getVisualDescription(componentName, component.category);

  // Key features
  output += `## Key Features\n\n`;
  output += getKeyFeatures(componentName, component.category);

  // Use cases
  output += `## Perfect For\n\n`;
  output += getUseCases(componentName, component.category);

  // Props overview
  output += `## Common Props\n\n`;
  output += getCommonProps(componentName, component.category);

  // Quick start
  output += `## Quick Start\n\n`;
  output += getQuickStart(componentName);

  // Available versions
  output += `## Available Versions\n\n`;
  output += `This component is available in 4 different tech stack combinations:\n\n`;
  output += `| Version | Description | Best For |\n`;
  output += `|---------|-------------|----------|\n`;
  output += `| js-css | JavaScript + CSS | Simple projects, learning |\n`;
  output += `| js-tailwind | JavaScript + Tailwind | Rapid prototyping, utility-first styling |\n`;
  output += `| ts-css | TypeScript + CSS | Type-safe projects with custom styling |\n`;
  output += `| ts-tailwind | TypeScript + Tailwind | Production apps, full type safety |\n\n`;

  // Performance notes
  output += `## Performance Notes\n\n`;
  output += getPerformanceNotes(componentName, component.category);

  // Browser support
  output += `## Browser Support\n\n`;
  output += getBrowserSupport(componentName, component.category);

  // Next steps
  output += `## Next Steps\n\n`;
  output += `1. **Get the code**: \`get-react-bits-component --componentName ${componentName} --version js-css\`\n`;
  output += `2. **See examples**: \`get-react-bits-demo --componentName ${componentName}\`\n`;
  output += `3. **Installation guide**: \`get-react-bits-install-guide --componentName ${componentName}\`\n`;
  output += `4. **Explore similar**: \`search-react-bits-components --category ${component.category}\`\n\n`;

  // Related components
  output += `## Related Components\n\n`;
  output += getRelatedComponents(componentName, component.category);

  return output;
}

