/**
 * Get key features for the component
 */
function getKeyFeatures(componentName, category) {
  const baseFeatures = [
    '✅ Fully customizable props',
    '✅ Responsive design ready',
    '✅ Smooth animations',
    '✅ TypeScript support',
    '✅ Tailwind CSS compatible'
  ];

  const categoryFeatures = {
    'animations': [
      '✅ Configurable timing and easing',
      '✅ Trigger-based animations',
      '✅ Performance optimized'
    ],
    'components': [
      '✅ Interactive elements',
      '✅ Event handling',
      '✅ Accessibility features'
    ],
    'backgrounds': [
      '✅ Full viewport coverage',
      '✅ Layering support',
      '✅ Performance optimized for backgrounds'
    ],
    'text-animations': [
      '✅ Character-by-character animation',
      '✅ Stagger effects',
      '✅ Typography-focused'
    ]
  };

  const features = [...baseFeatures];
  if (categoryFeatures[category]) {
    features.push(...categoryFeatures[category]);
  }

  // Component-specific features
  const specificFeatures = {
    'stack': ['✅ Gesture controls', '✅ Card stacking physics'],
    'dock': ['✅ Magnification effects', '✅ Icon positioning'],
    'model-viewer': ['✅ 3D rendering', '✅ WebGL support'],
    'particles': ['✅ Physics simulation', '✅ Customizable particle behavior']
  };

  if (specificFeatures[componentName]) {
    features.push(...specificFeatures[componentName]);
  }

  return features.join('\n');
}

