/**
 * Get common props for the component
 */
function getCommonProps(componentName, category) {
  let props = `\`\`\`typescript\ninterface ${capitalizeFirst(componentName)}Props {\n`;
  
  // Base props
  props += `  className?: string;           // Custom CSS classes\n`;
  props += `  style?: CSSProperties;        // Inline styles\n`;
  
  // Category-specific props
  switch (category) {
    case 'animations':
      props += `  duration?: number;            // Animation duration (seconds)\n`;
      props += `  delay?: number;               // Animation delay (seconds)\n`;
      props += `  easing?: string;              // Animation easing function\n`;
      break;
    case 'components':
      props += `  onClick?: () => void;         // Click handler\n`;
      props += `  disabled?: boolean;           // Disabled state\n`;
      break;
    case 'backgrounds':
      props += `  intensity?: number;           // Effect intensity (0-1)\n`;
      props += `  color?: string;               // Primary color\n`;
      props += `  speed?: number;               // Animation speed\n`;
      break;
    case 'text-animations':
      props += `  text: string;                 // Text to animate\n`;
      props += `  staggerDelay?: number;        // Delay between characters\n`;
      break;
  }
  
  // Component-specific props
  const specificProps = {
    'stack': `  items: StackItem[];           // Array of items to stack\n  maxVisible?: number;          // Maximum visible cards\n`,
    'dock': `  items: DockItem[];            // Array of dock items\n  magnification?: number;       // Hover magnification factor\n`,
    'spotlight-card': `  title?: string;               // Card title\n  description?: string;         // Card description\n  spotlightColor?: string;      // Spotlight color\n`
  };
  
  if (specificProps[componentName]) {
    props += specificProps[componentName];
  }
  
  props += `}\n\`\`\`\n\n`;
  props += `💡 **Note:** Actual props may vary. Use \`get-react-bits-component\` for complete prop definitions.`;
  
  return props;
}

/**
 * Get quick start code
 */
function getQuickStart(componentName) {
  return `\`\`\`bash\n# Install via JSRepo CLI\njsrepo add react-bits/${componentName}\n\`\`\`\n\n\`\`\`jsx\n// Basic usage\nimport ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';\n\nfunction App() {\n  return (\n    <div>\n      <${capitalizeFirst(componentName)} />\n    </div>\n  );\n}\n\`\`\``;
}

/**
 * Get performance notes
 */
function getPerformanceNotes(componentName, category) {
  let notes = '';
  
  if (category === 'animations' || category === 'backgrounds') {
    notes += '⚡ **Optimized for 60fps** - Uses hardware acceleration where possible\n';
    notes += '📱 **Mobile-friendly** - Reduced complexity on lower-end devices\n';
  }
  
  if (componentName.includes('3d') || componentName === 'model-viewer') {
    notes += '🎮 **WebGL required** - Ensure target browsers support WebGL\n';
    notes += '💾 **Memory usage** - Monitor memory usage with complex 3D scenes\n';
  }
  
  if (category === 'backgrounds') {
    notes += '🎨 **Background rendering** - Uses efficient rendering techniques\n';
  }
  
  if (!notes) {
    notes = '✅ **Lightweight** - Minimal performance impact\n';
    notes += '⚡ **Efficient** - Optimized for modern browsers\n';
  }
  
  return notes;
}

/**
 * Get browser support information
 */
function getBrowserSupport(componentName, category) {
  let support = '✅ **Modern browsers** - Chrome, Firefox, Safari, Edge (latest versions)\n';
  
  if (componentName.includes('3d') || componentName === 'model-viewer') {
    support += '🎮 **WebGL support required** - Check caniuse.com for WebGL compatibility\n';
  }
  
  if (category === 'animations') {
    support += '🎭 **CSS animations** - Requires modern CSS animation support\n';
  }
  
  support += '📱 **Mobile support** - iOS Safari 12+, Chrome Mobile 80+\n';
  
  return support;
}

/**
 * Get related components
 */
function getRelatedComponents(componentName, category) {
  const related = {
    'stack': ['dock', 'card-swap', 'bounce-cards'],
    'dock': ['stack', 'infinite-menu'],
    'spotlight-card': ['tilted-card', 'profile-card', 'decay-card'],
    'particles': ['orb', 'beams', 'lightning'],
    'model-viewer': ['fluid-glass', 'orb']
  };
  
  const componentRelated = related[componentName] || [];
  
  if (componentRelated.length === 0) {
    return `Explore more components in the **${category}** category using:\n\`search-react-bits-components --category ${category}\``;
  }
  
  let output = 'You might also like:\n\n';
  componentRelated.forEach(comp => {
    output += `- **${comp}** - \`get-react-bits-component --componentName ${comp}\`\n`;
  });
  
  return output;
}

/**
 * Utility function
 */
function capitalizeFirst(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}
